<h2>Condition scope and results</h2><?php foreach ($members as $m): $condition = $conditionsById[$m['vehicle_damage_item_id']]; ?><article class="work-scope"><h3><a href="/fleet/vehicles/<?= (int) $vehicle['id'] ?>/damage/<?= (int) $condition['id'] ?>"><?= esc(\Config\VehicleDamage::PANELS[$condition['panel_code'] ?? ''] ?? $condition['zone_code']) ?></a></h3><p><?= esc($condition['description']) ?></p><p>Physical condition: <strong><?= esc(\App\Services\Fleet\VehicleDamageService::STATUSES[$condition['status_code']]) ?></strong> · Work result: <?= esc(\Config\VehicleDamage::WORK_RESULTS[$m['result_code']]) ?></p><p>Result time: <?= esc((string) ($m['occurred_at'] ?? 'Not recorded / unknown')) ?></p><?php if ($m['note'] !== null): ?><p><?= nl2br(esc($m['note'])) ?></p><?php endif; ?>
<?php if ($m['withdrawn_at'] !== null): ?><p>Withdrawn from future scope: <?= esc($m['withdrawal_reason']) ?>. Prior work remains in history.</p>
<?php else: ?>
<?php if ($job['intent_code'] === 'repair' && $job['started_at'] !== null && in_array($job['status_code'], ['in_progress', 'deferred', 'completed'], true) && in_array($condition['status_code'], ['open', 'accepted_unrepaired'], true)): ?><p><a class="action-link" href="<?= $base ?>/conditions/<?= (int) $m['id'] ?>/confirm-repair">Inspect and confirm physical repair</a></p><?php endif; ?>
<?php if ($condition['status_code'] === 'repaired'): ?><p><a href="/fleet/vehicles/<?= (int) $vehicle['id'] ?>/damage/<?= (int) $condition['id'] ?>/reopen">Review and reopen failed / residual repair</a></p><?php endif; ?>
<?php if (($job['started_at'] !== null || $job['status_code'] === 'completed') && $m['result_code'] !== 'repaired'): ?><details class="capital-disclosure"><summary>Record / correct work result</summary><form action="<?= $base ?>/conditions/<?= (int) $m['id'] ?>/result" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'result']) ?><input type="hidden" name="expected_condition_state" value="<?= esc($fingerprints[$condition['id']], 'attr') ?>"><label>Result<select name="result_code"><?php foreach (\Config\VehicleDamage::WORK_RESULTS as $code => $label): if ($code === 'repaired' || ($job['intent_code'] === 'mitigation' && ! in_array($code, ['unassessed', 'unchanged', 'mitigated', 'failed'], true))) { continue; } ?><option value="<?= esc($code, 'attr') ?>" <?= ($formData['result_code'] ?? $m['result_code']) === $code ? 'selected' : '' ?>><?= esc($label) ?></option><?php endforeach; ?></select></label><label>Finding / reason<textarea name="note" required maxlength="2000"><?= esc((string) ($formData['note'] ?? $m['note'] ?? '')) ?></textarea></label><label>Outcome time (optional)<input type="datetime-local" name="occurred_at"></label><label>Correction reason<textarea name="reason" <?= $terminal ? 'required' : '' ?> maxlength="2000"><?= esc((string) ($formData['reason'] ?? '')) ?></textarea></label><button type="submit">Record result</button></form></details><?php endif; ?>
<?php if (! $terminal && count($activeMembers) > 1): ?><details class="capital-disclosure"><summary>Withdraw from future scope</summary><form action="<?= $base ?>/conditions/<?= (int) $m['id'] ?>/withdraw" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'withdraw']) ?><label>Withdrawal reason<textarea name="reason" required maxlength="2000"></textarea></label><button type="submit">Withdraw condition</button></form></details><?php endif; ?>
<?php endif; ?></article><?php endforeach; ?>
